#include "kstationControllerProgramRuntime.h"
#include "h8s/h8s.hpp"
#include <array>
#include <cstdio>
#include <fstream>
#include <memory>
#include <vector>
struct Ref: H8SEmulator {void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t time;uint32_t addr;uint8_t value;bool write;};
static bool observed(uint32_t a){return (a>=0xba00&&a<0xd400)||(a>=0x18000&&a<0x1a000)||(a>=0x220000&&a<0x240000);}
struct RBus:H8SDevice{Ref&c;std::array<Event,16>e{};unsigned n=0;explicit RBus(Ref&x):c(x){}uint8_t read(uint32_t a)override{auto v=c.memory[a];if(observed(a))e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(observed(a))e[n++]={c.cycles,a,v,true};c.memory[a]=v;}};
struct NBus:kstation::ControllerResourceBus{std::array<Event,16>e{};unsigned n=0;bool mapped(uint32_t a)const override{return observed(a);}uint8_t read(uint32_t a)override{auto v=state_->memory[a];e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;}};
int main(int argc,char**argv){if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),unsigned(rom.size()),0);d->loadMemory(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xba00,0x1a00);c->memmap(&x,0x18000,0x2000);c->memmap(&x,0x220000,0x20000);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerProgramRuntime rt;if(!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!rt.bindVerifiedFirmware(*d,rom.data(),rom.size()))return 2;for(uint32_t a:{0x165eu,0x571eu,0x816cu,0x763eu,0x4358u}){c->memory[a]=0x54;c->memory[a+1]=0x70;}uint64_t graphs=0,phases=0,events=0,shorts=0,services=0;for(unsigned flags=0;flags<256;++flags)for(uint8_t match:{uint8_t(0),uint8_t(1)})for(uint8_t bank:{uint8_t(0),uint8_t(1),uint8_t(255)})for(uint8_t program:{uint8_t(0),uint8_t(99),uint8_t(100),uint8_t(255)}){rt.reset();irq.reset();irq.setMask(kstation::ControllerInterruptRuntime::Mask::Disabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};put(0xcad3,program);put(0xcad5,3);put(0xbb16,match?3:4);put(0xcbff,bank);put(0xcd82,0x55);put(0xcd83,0xaa);c->pc=c->makepc(0x33ca);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg32(4)=0xcad3;c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;if(!rt.start(3,0xcad3))return 3;for(unsigned k=0;rt.active();++k){if(k>20000)return 4;auto req=rt.request();x.n=y.n=0;auto at=uint32_t(c->getPC());if(req.service!=kstation::ControllerProgramRuntime::Service::None){auto target=req.service==kstation::ControllerProgramRuntime::Service::DspWrite?0x165e:req.service==kstation::ControllerProgramRuntime::Service::RefreshPanel?0x571e:req.service==kstation::ControllerProgramRuntime::Service::InitializeVoice?0x816c:req.service==kstation::ControllerProgramRuntime::Service::ReleaseVoices?0x763e:0x4358;if(at!=target){std::fprintf(stderr,"program request pc=%x expected=%x service=%u\n",at,target,unsigned(req.service));return 5;}if(req.service==kstation::ControllerProgramRuntime::Service::DspWrite&&(uint16_t(c->reg16(4))!=req.address||(uint32_t(c->reg32(1))>>8)!=req.word))return 14;c->step();d->cycles+=7;d->lastRead=-1;if(!rt.completeService(req.service))return 6;++services;}else{auto budget=rt.nextClocks(*d,irq);if(!budget)return 7;auto before=d->cycles;for(unsigned b=0;b<budget;++b){auto r=rt.advanceBefore(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 8;++shorts;}c->step();auto r=rt.advanceBefore(*d,irq,budget);if(!r.clocks)return 9;}if(c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x clocks=%llu/%llu io=%u/%u\n",at,c->cycles,d->cycles,x.n,y.n);return 10;}for(unsigned i=0;i<x.n;++i)if(x.e[i].time!=y.e[i].time||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write)return 11;events+=x.n;++phases;}if(c->getPC()!=0x7000)return 12;for(uint32_t a:{0xcbffu,0xcd82u,0xcd83u})if(c->memory[a]!=d->memory[a])return 13;++graphs;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu,\"external_services\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts,(unsigned long long)services);}
